#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <pthread.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <stdint.h>

#define MAX_CONCURRENT_INFERENCES 64
#define MODEL_CACHE_DIR "/tmp/ml_inference_cache"
#define TENSOR_BUFFER_SIZE 4096

typedef struct {
    int session_id;
    char model_name[256];
    float *input_tensor;
    size_t tensor_size;
    int status;
} InferenceRequest;

typedef struct {
    char path[512];
    int fd;
    int is_active;
} TensorCache;

static TensorCache cache_slots[MAX_CONCURRENT_INFERENCES];
static pthread_mutex_t cache_mutex = PTHREAD_MUTEX_INITIALIZER;
static volatile int next_slot = 0;

/* Creates a unique path for tensor serialization based on session context */
static int derive_cache_path(char *out_path, size_t out_len, int session_id, const char *model_name) {
    unsigned long hash = 5381;
    const char *p = model_name;
    while (*p) {
        hash = ((hash << 5) + hash) + (unsigned char)(*p++);
    }
    hash ^= (unsigned long)session_id;
    snprintf(out_path, out_len, "%s/tensor_%lx_%d.bin", MODEL_CACHE_DIR, hash, session_id);
    return 0;
}

/* Ensures the cache directory exists with appropriate permissions */
static int ensure_cache_dir(void) {
    struct stat st;
    if (stat(MODEL_CACHE_DIR, &st) == -1) {
        if (mkdir(MODEL_CACHE_DIR, 0700) == -1 && errno != EEXIST) {
            return -1;
        }
    }
    return 0;
}

/* Allocates a cache slot for the current inference operation */
static int allocate_cache_slot(int session_id, const char *model_name) {
    pthread_mutex_lock(&cache_mutex);
    int slot = next_slot;
    next_slot = (next_slot + 1) % MAX_CONCURRENT_INFERENCES;

    if (cache_slots[slot].is_active) {
        /* Evict previous entry */
        if (cache_slots[slot].fd >= 0) {
            close(cache_slots[slot].fd);
        }
        unlink(cache_slots[slot].path);
    }

    derive_cache_path(cache_slots[slot].path, sizeof(cache_slots[slot].path), session_id, model_name);
    cache_slots[slot].is_active = 1;
    cache_slots[slot].fd = -1;
    pthread_mutex_unlock(&cache_mutex);
    return slot;
}

/* Opens the tensor cache file for writing intermediate results.
 * Uses atomic open with O_NOFOLLOW to prevent symlink attacks.
 * The O_EXCL flag ensures we never open an existing file. */
static int open_cache_file(int slot) {
    /* Remove any existing file at this path first */
    unlink(cache_slots[slot].path);

    /* Atomically create and open - O_EXCL ensures no race condition,
     * O_NOFOLLOW prevents symlink following */
    int fd = open(cache_slots[slot].path, O_WRONLY | O_CREAT | O_EXCL | O_NOFOLLOW, 0600);
    if (fd < 0) {
        return -1;
    }
    cache_slots[slot].fd = fd;
    return 0;
}

/* Serializes tensor data to the cache for later retrieval */
static int serialize_tensor(int slot, const float *data, size_t count) {
    /* Guard against integer overflow when computing the byte length. */
    if (count > SIZE_MAX / sizeof(float)) {
        return -1;
    }
    size_t byte_len = count * sizeof(float);

    if (cache_slots[slot].fd < 0) {
        if (open_cache_file(slot) != 0) {
            return -1;
        }
    }

    ssize_t written = write(cache_slots[slot].fd, data, byte_len);
    if (written != (ssize_t)byte_len) {
        return -1;
    }
    return 0;
}

/* Main inference pipeline - processes a single request */
static int run_inference(InferenceRequest *req) {
    if (ensure_cache_dir() != 0) {
        req->status = -1;
        return -1;
    }

    int slot = allocate_cache_slot(req->session_id, req->model_name);

    /* Serialize input tensor to cache for checkpointing */
    if (serialize_tensor(slot, req->input_tensor, req->tensor_size) != 0) {
        req->status = -2;
        return -1;
    }

    /* Simulate model forward pass */
    for (size_t i = 0; i < req->tensor_size; i++) {
        req->input_tensor[i] = req->input_tensor[i] * 0.5f + 0.1f;
    }

    /* Write output checkpoint */
    if (serialize_tensor(slot, req->input_tensor, req->tensor_size) != 0) {
        req->status = -3;
        return -1;
    }

    /* Cleanup */
    close(cache_slots[slot].fd);
    cache_slots[slot].fd = -1;
    unlink(cache_slots[slot].path);
    cache_slots[slot].is_active = 0;

    req->status = 0;
    return 0;
}

/* Worker thread for concurrent inference */
static void *inference_worker(void *arg) {
    InferenceRequest *req = (InferenceRequest *)arg;
    run_inference(req);
    return NULL;
}

int main(int argc, char **argv) {
    memset(cache_slots, 0, sizeof(cache_slots));
    for (int i = 0; i < MAX_CONCURRENT_INFERENCES; i++) {
        cache_slots[i].fd = -1;
    }

    /* Example: run 4 concurrent inferences */
    pthread_t threads[4];
    InferenceRequest requests[4];
    float tensors[4][TENSOR_BUFFER_SIZE];

    for (int i = 0; i < 4; i++) {
        requests[i].session_id = 1000 + i;
        snprintf(requests[i].model_name, sizeof(requests[i].model_name), "resnet50_v%d", i);
        requests[i].input_tensor = tensors[i];
        requests[i].tensor_size = TENSOR_BUFFER_SIZE;
        requests[i].status = -99;

        for (int j = 0; j < TENSOR_BUFFER_SIZE; j++) {
            tensors[i][j] = (float)j / TENSOR_BUFFER_SIZE;
        }

        pthread_create(&threads[i], NULL, inference_worker, &requests[i]);
    }

    for (int i = 0; i < 4; i++) {
        pthread_join(threads[i], NULL);
        printf("Inference %d completed with status: %d\n", i, requests[i].status);
    }

    return 0;
}
